// Sortie structurée du cœur RAG, utilisée par le chat (WF2) et les évaluations (WF3).
const c = $('Construire le contexte').first().json;
const reponse = String($input.first().json.text || '').trim();
return [{ json: {
  reponse,
  refus: reponse.includes('Information non trouvée dans la documentation'),
  docs_recuperes: c.docs_recuperes,
  passages: c.passages,
  contexte: c.contexte,
  top_k: c.top_k,
  modele: c.modele,
  prompt_version: c.prompt_version,
  duree_ms: Date.now() - c.t0,
} }];
